import React from "react";
import Image from "next/image";
// Replace with your image path

const WhyChooseHat = () => {
    const features = [
        { title: "10K+", description: "Happy Customers" },
        { title: "24/7", description: "Customer Support" },
        { title: "100%", description: "Quality Assurance" },
    ];

    return (
        <section className="w-full bg-white py-20 px-6 md:px-12 lg:px-20">
            <div className="max-w-7xl mx-auto grid    lg:grid-cols-2 gap-10 items-center">
                {/* LEFT SIDE - Girl Image */}
                <div className="flex justify-center relative">
                    <div className="relative w-72 h-72 md:w-96 md:h-96">
                        <Image
                            src="/public/Services/girlImage.png"
                            alt="Why Choose Us Illustration"
                            fill
                            className="object-contain drop-shadow-2xl"
                        />
                    </div>
                </div>

                {/* RIGHT SIDE - Text + Boxes */}
                <div className="space-y-6">
                    <h2 className="text-4xl md:text-5xl font-bold text-gray-900">
                        Why Choose <span className="text-blue-600">Hat</span>?
                    </h2>
                    <p className="text-gray-600 text-lg max-w-md">
                        We deliver the best-in-class experience with a focus on innovation,
                        reliability, and customer satisfaction. Our dedicated team ensures
                        your journey is seamless from start to finish.
                    </p>

                    {/* Feature Boxes */}
                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-6 pt-6">
                        {features.map((item, index) => (
                            <div
                                key={index}
                                className="bg-blue-50 hover:bg-blue-100 transition-all duration-300 rounded-2xl shadow-md p-6 text-center"
                            >
                                <h3 className="text-2xl font-bold text-blue-600">
                                    {item.title}
                                </h3>
                                <p className="text-gray-700 mt-2">{item.description}</p>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </section>
    );
};

export default WhyChooseHat;
